H.circle(xR, roadY, 6, { fill: H.colors.warn });
H.text("start", xL, roadY - 14, { color: H.colors.sub, size: 12, align: "center" });
H.text(dist.toFixed(0) + " mi", xR, roadY - 14, { color: H.colors.sub, size: 12, align: "center" });
const frac = (t / T) % 1;
const carX = xL + frac * (xR - xL);
H.rect(carX - 12, roadY - 9, 24, 12, { fill: H.colors.accent, radius: 3 });
H.circle(carX - 6, roadY + 5, 3, { fill: H.colors.ink });
H.circle(carX + 6, roadY + 5, 3, { fill: H.colors.ink });
